module uart_rx_heart(
	sys_clk,
	sys_rst_n,
	uart_rxd,
	rx_en,
	uart_data,
	uart_done,
	uart_get,
	pack_cnt,
	pack_ing,
	pack_done,
	pack_num,
	recv_done,
	dataA,
	dataB,
	dataC,
	dataD,
	dataE);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input sys_rst_n;
	input uart_rxd;
	input rx_en;
	output [7:0] uart_data;
	output uart_done;
	output uart_get;
	output [7:0] pack_cnt;
	output pack_ing;
	output pack_done;
	output [7:0] pack_num;
	output recv_done;
	output [7:0] dataA;
	output [7:0] dataB;
	output [7:0] dataC;
	output [7:0] dataD;
	output [7:0] dataE;

	wire sys_clk;
	wire sys_rst_n;
	wire uart_rxd;
	wire rx_en;
	reg [7:0] uart_data;
	reg uart_done;
	reg uart_get;
	reg [7:0] pack_cnt;
	reg pack_ing;
	reg pack_done;
	reg [7:0] pack_num;
	reg recv_done;
	reg [7:0] dataA;
	reg [7:0] dataB;
	reg [7:0] dataC;
	reg [7:0] dataD;
	reg [7:0] dataE;

	//----Code starts here: integrated by Robei-----
	localparam  DATA_NUM = 12;//+SPO2=100OK
	integer j;
	
	reg [7:0] pack_data [DATA_NUM-1:0];           //接收的数据         改 二维数组是8位
	//parameter define
	parameter  CLK_FREQ = 33_000_000;                 //系统时钟频率
	parameter  UART_BPS = 9600;                     //串口波特率
	localparam BPS_CNT  = 6;//便于仿真，正常为CLK_FREQ/UART_BPS
	 
	localparam  TimeOut = BPS_CNT*DATA_NUM*10*2;//超时时间
	
	//起始信号下降沿捕捉
	wire       start_flag;
	reg        uart_rxd_d0;
	reg        uart_rxd_d1;
	
	reg [15:0] clk_cnt;                             //系统时钟计数器
	reg [ 3:0] rx_cnt;                              //接收数据计数器
	reg        rx_flag;                             //接收过程标志信号
	reg [ 7:0] rxdata;                              //接收数据寄存器
	
	//接收信号完成标志位上升沿
	wire  rxdone_flag;
	reg   uart_done_d0;
	reg   uart_done_d1;
	//包数据接收完成
	wire  packdone_flag;
	reg   pack_done_d0;
	reg   pack_done_d1;
	
	//*******************************************//
	//**                    main code
	//*******************************************//
	//捕获接收端口下降沿(起始位)，得到一个时钟周期的脉冲信号
	assign  start_flag = uart_rxd_d1 & (~uart_rxd_d0);    
	//对UART接收端口的数据延迟两个时钟周期
	always @(posedge sys_clk or negedge sys_rst_n) begin 
	    if (!sys_rst_n) begin 
	        uart_rxd_d0 <= 1'b0;
	        uart_rxd_d1 <= 1'b0;          
	    end
	    else begin
	        uart_rxd_d0  <= uart_rxd;                   
	        uart_rxd_d1  <= uart_rxd_d0;
	    end   
	end
	//当脉冲信号start_flag到达时，进入接收过程           
	always @(posedge sys_clk or negedge sys_rst_n) begin         
	    if (!sys_rst_n)                                  
	        rx_flag <= 1'b0;
	    else begin
	        if(start_flag && rx_en == 1'b1)                          //检测到起始位
	            rx_flag <= 1'b1;                    //进入接收过程，标志位rx_flag拉高
	        else if((rx_cnt == 4'd9)&&(clk_cnt == BPS_CNT/2))
	            rx_flag <= 1'b0;                    //计数到停止位中间时，停止接收过程
	        else
	            rx_flag <= rx_flag;
	    end
	end
	//进入接收过程后，启动系统时钟计数器与接收数据计数器
	always @(posedge sys_clk or negedge sys_rst_n) begin         
	    if (!sys_rst_n) begin                             
	        clk_cnt <= 16'd0;                                  
	        rx_cnt  <= 4'd0;
	    end                                                      
	    else if ( rx_flag ) begin                   //处于接收过程
	            if (clk_cnt < BPS_CNT - 1) begin
	                clk_cnt <= clk_cnt + 1'b1;
	                rx_cnt  <= rx_cnt;
	            end
	            else begin
	                clk_cnt <= 16'd0;               //对系统时钟计数达一个波特率周期后清零
	                rx_cnt  <= rx_cnt + 1'b1;       //此时接收数据计数器加1
	            end
	        end
	        else begin                              //接收过程结束，计数器清零
	            clk_cnt <= 16'd0;
	            rx_cnt  <= 4'd0;
	        end
	end
	//根据接收数据计数器来寄存uart接收端口数据
	always @(posedge sys_clk or negedge sys_rst_n) begin 
	    if (!sys_rst_n)  begin
	        rxdata <= 8'd0;     
			  uart_get<=1'b0;		
		 end  
	    else if(rx_flag)                            //系统处于接收过程
	        if (clk_cnt == BPS_CNT/2) begin         //判断系统时钟计数器计数到数据位中间
	            case ( rx_cnt )
	             4'd1 : rxdata[0] <= uart_rxd_d1;   //寄存数据位最低位
	             4'd2 : rxdata[1] <= uart_rxd_d1;
	             4'd3 : rxdata[2] <= uart_rxd_d1;
	             4'd4 : rxdata[3] <= uart_rxd_d1;
	             4'd5 : rxdata[4] <= uart_rxd_d1;
	             4'd6 : rxdata[5] <= uart_rxd_d1;
	             4'd7 : rxdata[6] <= uart_rxd_d1;
	             4'd8 : rxdata[7] <= uart_rxd_d1;   //寄存数据位最高位
	             default:;                                    
	            endcase
					uart_get<=1'b1;	
	        end
	        else  begin
	            rxdata <= rxdata;
					uart_get<=1'b0;	
			  end
	    else begin
	        rxdata <= 8'd0;
			  uart_get<=1'b0;	
		 end
	end
	
	
	//数据接收完毕后给出标志信号并寄存输出接收到的数据
	always @(posedge sys_clk or negedge sys_rst_n) begin        
	    if (!sys_rst_n) begin
	        uart_data <= 8'd0;                               
	        uart_done <= 1'b0;
	    end
	    else if(rx_cnt == 4'd9) begin               //接收数据计数器计数到停止位时           
	        uart_data <= rxdata;                    //寄存输出接收到的数据
	        uart_done <= 1'b1;                      //并将接收完成标志位拉高
	    end
	    else begin
	        uart_data <= 8'd0;                                   
	        uart_done <= 1'b0; 
	    end    
	end
	
	//---单字节接收程序，uart_done接收完成标志位会持续半个波特率周期，捕捉上升沿可以计数，高电平状态，接收数据有效
	//==============================================接收多个字节，添加的模块====================================================//
	
	//捕获接收完成标志位的上升沿，得到一个时钟周期的脉冲信号
	assign  rxdone_flag = uart_done_d0 & (~uart_done_d1);    
	//对UART完成标志的数据延迟两个时钟周期
	always @(posedge sys_clk or negedge sys_rst_n) begin 
	    if (!sys_rst_n) begin 
	        uart_done_d0 <= 1'b0;
	        uart_done_d1 <= 1'b0;          
	    end
	    else begin
	        uart_done_d0  <= uart_done;                   
	        uart_done_d1  <= uart_done_d0;
	    end   
	end
	
	//接收到的数据存入数组中，并计数
	always @(posedge sys_clk or negedge sys_rst_n) begin      //接收到数据  
	    if (!sys_rst_n) begin                             
			  pack_cnt <=8'd0;
			  pack_num <=8'd0;
			  pack_done<=1'b0; 
			  pack_ing <=1'b0;
			  for (j=0;j<DATA_NUM;j=j+1) 
			    pack_data[j] <= 8'd0;		 
	    end
		 else if(rxdone_flag) begin //接收完成标志位的上升沿，延迟了两个时钟周期
			 if (pack_cnt < DATA_NUM-1) begin       //处于接收过程中
					 for (j=0;j<DATA_NUM;j=j+1) begin
					     if(j==pack_cnt)
						    pack_data[pack_cnt] <= uart_data;//寄存输出接收到的数据
						  else
						    pack_data[j] <= pack_data[j];	
					 end
					 pack_cnt  <= pack_cnt + 1'b1; 
	             pack_num <= 8'd0;	
			       pack_done<=1'b0; 
			       pack_ing <=1'b1;		 
			 end
			 else begin //接收完成---最后一个字节的接收
					 for (j=0;j<DATA_NUM;j=j+1) begin
					     if(j==pack_cnt)
						  pack_data[pack_cnt] <= uart_data;//寄存输出接收到的数据
						  else
						  pack_data[j] <= pack_data[j];	
					 end
					 pack_num <= pack_cnt + 1'b1; //加上最后一个字节
				    pack_cnt  <= 8'd0;               //此时接收数据计数器归零，只有接收完成时才清零
					 pack_done<=1'b1;      			 //输出帧接收完成标志位，只存在一个周期
					 pack_ing <=1'b0;
			 end  
		 end
		 else begin
			  pack_cnt <=pack_cnt;
			  pack_ing <=pack_ing;//保持
			  pack_num <=pack_num;
			  pack_done<=1'b0;  
			  for (j=0;j<DATA_NUM;j=j+1) 
			    pack_data[j] <= pack_data[j];	
		 end
	end
	
	
	//------------解码-------------------------//
	//捕获接收完成标志位的上升沿，得到一个时钟周期的脉冲信号
	assign  packdone_flag = pack_done_d0 & (~pack_done_d1);    
	//对UART完成标志的数据延迟两个时钟周期
	always @(posedge sys_clk or negedge sys_rst_n) begin 
	    if (!sys_rst_n) begin 
	        pack_done_d0 <= 1'b0;
	        pack_done_d1 <= 1'b0;          
	    end
	    else begin
	        pack_done_d0  <= pack_done;                   
	        pack_done_d1  <= pack_done_d0;
	    end   
	end
	
	always @(posedge sys_clk or negedge sys_rst_n) begin         
	    if (!sys_rst_n) begin                             
	       dataA <= 8'd0; 
			 dataB <= 16'd0;
			 dataC <=16'd0;
			 dataD <=16'd0;
			 dataE <=16'd0;
			 recv_done <=1'b0;
	    end  
		 else if(packdone_flag) begin //数据接收完成，进行解码
			 if(pack_num==DATA_NUM && pack_data[0]==8'h2B && pack_data[4]==8'h32 && pack_data[5]==8'h3D ) begin  //判断血氧数据正误+SPO2=NULLOK
				 dataA <=pack_data[6];
				 dataB <= pack_data[7];
				 dataC <= pack_data[8];
				 dataD <= pack_data[9];
				 dataE <= pack_data[4];
				 recv_done <=1'b1;
			 end 
			 else if(pack_num==DATA_NUM && pack_data[0]==8'h2B && pack_data[4]==8'h52 && pack_data[5]==8'h54 ) begin  //判断数据正误+HEART=NULLOK
				 dataA <=pack_data[7];
				 dataB <= pack_data[8];
				 dataC <= pack_data[9];
				 dataD <= pack_data[10];
				 dataE <= pack_data[4];
				 recv_done <=1'b1;
			 end 
			 else begin //数据错误
				 dataA <= 8'd1; 
				 dataB <= 16'd0;
				 dataC <=16'd0;
				 dataD <=16'd0;
				 dataE <=16'd0;
				 recv_done <=1'b0;
			 end
		 end
		 else begin //数据保持到下一个周期，标志位保持一个周期
			 dataA <= dataA; 
			 dataB <= dataB;
			 dataC <=dataC;
			 dataD <=dataD;
			 dataE <=dataE;
			 recv_done <=1'b0;
		 end	 
	end
	
	
	
	
endmodule    //uart_rx_heart

